function electricEffect(from,to){const group=new THREE.Group();const glow=new THREE.LineBasicMaterial({color:'#ffe974',transparent:true,opacity:1});const white=new THREE.LineBasicMaterial({color:'#fffce4',transparent:true,opacity:1});for(let strand=0;strand<4;strand++){const points=[];for(let i=0;i<=12;i++){const v=from.clone().lerp(to,i/12);if(i&&i<12){v.x+=(Math.random()-.5)*.55;v.y+=(Math.random()-.5)*.55;v.z+=(Math.random()-.5)*.55;}points.push(v);}group.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(points),strand===0?white:glow));}const burst=mesh(new THREE.IcosahedronGeometry(.35,1),new THREE.MeshBasicMaterial({color:'#ffe77e',transparent:true,opacity:.65}),to.x,to.y,to.z,group);const light=new THREE.PointLight('#ffe68c',7,7);light.position.copy(to);group.add(light);effect(group,.4,'electric');}
