$('build').onclick=()=>{if(won)return;const boards=selectedBoards(),result=bridgeResult(boards.map(b=>b.length),guardBeaten);if(result.reason==='count'){$('feedback').textContent='Choose exactly two boards. 请选择两块木板。';return;}if(result.reason==='guard'){$('feedback').textContent='Defeat the guardian first. 先击败守卫。';return;}if(!result.ok){$('feedback').textContent=`${result.sum} cm is too short. 还差 ${100-result.sum} cm。`;showBubble('We need longer boards.','还需要更长的木板。');return;}won=true;bridge.visible=true;waitingBoards.visible=false;celebrate=2.8;const equation=boards.map(b=>b.length).join(' + ');for(let i=inventory.length-1;i>=0;i--)if(selected.has(inventory[i].id))inventory.splice(i,1);selected.clear();drawInventory();$('total').textContent=`${result.sum} / 100 cm`;$('measurefill').style.width='100%';$('feedback').textContent=`${equation} = ${result.sum} cm ≥ 100 cm`;$('build').textContent='Bridge ready ✓';$('build').disabled=true;$('reset').hidden=false;document.body.classList.remove('bag-open');$('bag-toggle').setAttribute('aria-expanded','false');selectedMob=null;autoClaw=false;showBubble('We built it together!','一起过桥，回家啦！');toast('Bridge complete! 🌿','找材料、学技能、拼木板，你都做到了！');target.set(10,0,1);updateCombatUI();};
