let storyIndex=0,storyTime=0,storySeen=false,storyFrom=new THREE.Vector3();
function setStoryShot(i){storyIndex=i;storyTime=0;storyFrom.copy(camera.position);const s=storyShots[i];$('story-title').textContent=s.title;$('story-title').dataset.translation=s.zh;$('story-text').textContent=s.text;$('story-text').dataset.translation=s.zh;$('story-count').textContent=`0${i+1} / 04`;$('story-next').textContent=i===3?'Let’s go!':'Next';}
function startIntro(){introActive=true;storySeen=true;keys.clear();target.copy(player);selectedMob=null;autoClaw=false;queuedSkill=null;$('story').hidden=false;document.body.classList.add('story-playing');setStoryShot(0);}
